#include <iostream>
#include <vector>
using namespace std;

const int MOD = 1000000007;

int main() {
    int p, k;
    cin >> p >> k;
    int res = 1;

    if (k == 0) {
        for (int i = 1; i < p; ++i)
            res = (long long)res * p % MOD;
        cout << res;
        return 0;
    }

    if (k == 1) {
        for (int i = 0; i < p; ++i)
            res = (long long)res * p % MOD;
        cout << res;
        return 0;
    }

    vector<long long> powk(p + 1, 1);
    for (int i = 1; i <= p; ++i)
        powk[i] = (powk[i - 1] * k) % p;

    vector<bool> mark(p, false);
    for (int i = 1; i < p; ++i) {
        if (!mark[i]) {
            int j = i, length = 0;
            do {
                mark[j] = true;
                ++length;
                j = (long long)k * j % p;
            } while (!mark[j]);
            if (powk[length] == 1)
                res = (long long)res * p % MOD;
        }
    }

    cout << res;
    return 0;
}
